///|
/// Bind the selected output quota to one original Calendar occurrence. This
/// does not replace its conservative preparation/capacity upper bound.
pub fn constrain_generated_calendar_output(
  generated : GeneratedSequence,
  step : Int,
  ceiling : Int64,
) -> Result[GeneratedSequence, SequenceRunIssue] {
  if ceiling < 0L {
    return Err(InvalidLimits)
  }
  guard @lower.sequence_step(generated.sequence, step)
    is Some(@lower.CalendarStep(calendar)) &&
    @lower.calendar_step(calendar) == step else {
    return Err(InputSet)
  }
  let ceilings = generated.calendar_output_ceilings.copy()
  for index, (prior_step, prior) in ceilings {
    if prior_step == step {
      ceilings[index] = (step, Int64::min(prior, ceiling))
      return Ok({ ..generated, calendar_output_ceilings: ceilings, })
    }
  }
  ceilings.push((step, ceiling))
  Ok({ ..generated, calendar_output_ceilings: ceilings, })
}

